// Reference implementation — the deterministic anti-pattern detector (step 7a).
// Runs inline on 100% of output in <10ms. Hard rules fail (and the mechanical
// ones auto-repair); soft rules only fail on accumulation. Replace the RULES
// with YOUR team's named quality bar — these examples are illustrative, not law.

export interface Rule {
  id: string;
  test: RegExp;
  repair?: (s: string) => string; // present => mechanically fixable, applied in-memory
}

// HARD rules: one hit = fail. Give the fixable ones a `repair`.
export const HARD_RULES: Rule[] = [
  { id: 'em-dash', test: /—/g, repair: s => s.replace(/\s*—\s*/g, ', ') },
  { id: 'double-space', test: /  +/g, repair: s => s.replace(/  +/g, ' ') },
  // ... your named anti-patterns go here (e.g. banned phrases, forbidden framings)
];

// SOFT rules: a single hit is fine; N+ within a window is a tic. One shared
// regex of "tell" words; the threshold is what flags it.
export const SOFT_TELLS = /\b(delve|nuanced|intricate|palpable|profound|evocative|tapestry|realm)\b/gi;
const SOFT_THRESHOLD = 2; // 2+ tells per ~200 words = flag

export interface CritiqueResult {
  pass: boolean;
  repaired: string;          // the (possibly auto-repaired) text
  hardFindings: string[];    // rule ids that fired after repair
  softCount: number;
  autoRepairs: number;
}

export function critique(input: string): CritiqueResult {
  let text = input;
  let autoRepairs = 0;

  // Apply mechanical repairs first, count them.
  for (const rule of HARD_RULES) {
    if (rule.repair && rule.test.test(text)) {
      const before = text;
      text = rule.repair(text);
      if (text !== before) autoRepairs++;
    }
  }

  // Re-check hard rules AFTER repair — only unrepairable residue counts.
  const hardFindings = HARD_RULES
    .filter(r => { r.test.lastIndex = 0; return r.test.test(text); })
    .map(r => r.id);

  const softCount = (text.match(SOFT_TELLS) ?? []).length;

  return {
    pass: hardFindings.length === 0 && softCount < SOFT_THRESHOLD,
    repaired: text,
    hardFindings,
    softCount,
    autoRepairs,
  };
}

// Reference implementation — the fail-open prompt assembler (step 2 + 3).
// Provider-neutral: you supply a PromptStore (Langfuse / LangSmith / Braintrust /
// your own) and an in-code fallback. Adapt types to your stack; do not copy blind.
//
// The one invariant: assemble() NEVER throws on a store outage. Telemetry may
// degrade; user delivery never fails.

export interface ManagedPrompt {
  version: string;
  template: string; // may contain {{variables}}
}

export interface PromptStore {
  // Fetch the prompt labeled `production` for this name. May throw / time out —
  // the assembler is responsible for surviving that.
  fetch(name: string, label?: string): Promise<ManagedPrompt>;
}

// ---- short-TTL cache with an indefinitely-held last-good fallback (step 3) ----

interface CacheEntry { value: ManagedPrompt; fetchedAt: number; }

export class PromptCache {
  private fresh = new Map<string, CacheEntry>();
  private lastGood = new Map<string, ManagedPrompt>(); // never evicted

  constructor(
    private store: PromptStore,
    private ttlMs = 10_000,
    private now: () => number = () => Date.now(),
  ) {}

  async get(name: string): Promise<ManagedPrompt | null> {
    const hit = this.fresh.get(name);
    if (hit && this.now() - hit.fetchedAt < this.ttlMs) return hit.value;
    try {
      const value = await this.store.fetch(name, 'production');
      this.fresh.set(name, { value, fetchedAt: this.now() });
      this.lastGood.set(name, value); // remember the last thing that worked
      return value;
    } catch {
      // Store is down or slow. Serve the last thing that worked, forever.
      return this.lastGood.get(name) ?? null;
    }
  }
}

// ---- the assembler: managed -> compile -> in-code fallback -> usable default ----

export interface AssembleArgs {
  name: string;
  variables?: Record<string, string>;
  fallbackTemplate: string;   // the in-code cold-start copy (step 1)
  lastResort?: string;        // returned if even compilation fails; default ''
}

export interface AssembledPrompt {
  text: string;
  source: 'managed' | 'fallback' | 'lastResort';
  version?: string;           // set when source === 'managed' (link this in traces, step 5)
}

function compile(template: string, vars: Record<string, string> = {}): string {
  return template.replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => vars[k] ?? '');
}

export async function assemble(
  cache: PromptCache,
  { name, variables, fallbackTemplate, lastResort = '' }: AssembleArgs,
): Promise<AssembledPrompt> {
  try {
    const managed = await cache.get(name);
    if (managed) {
      return { text: compile(managed.template, variables), source: 'managed', version: managed.version };
    }
  } catch {
    // fall through — never let the store break delivery
  }
  try {
    return { text: compile(fallbackTemplate, variables), source: 'fallback' };
  } catch {
    return { text: lastResort, source: 'lastResort' };
  }
}

// Reference implementation — the grounding gate (steps 2, 4, 8) + the grade
// primitive (step 7). Provider-neutral. Adapt to your fact shape; don't copy blind.
//
// Core idea: classify every fact as GROUNDED, SILENT, or VIOLATION. Only GROUNDED
// facts reach the model. SILENT is honest absence. VIOLATION never ships and is
// what you measure against.

export interface Fact {
  value: unknown;
  source?: string;
  observedAt?: number;   // epoch ms
  confidence?: number;   // 0..1
  ttlMinutes?: number;   // producer-declared freshness; falls back to default
  silentReason?: string; // set => a typed absence, not a claim
}

export type Verdict =
  | { kind: 'GROUNDED'; fact: Fact }
  | { kind: 'SILENT'; reason: string }
  | { kind: 'VIOLATION'; reason: string; cardinal: boolean };

const CARDINAL_CONFIDENCE = 0.7;   // confidence >= this with no source = impossible
const DEFAULT_TTL_MINUTES = 1440;  // conservative: unknowns are NOT spoken as fresh

export function classify(fact: Fact, now = Date.now()): Verdict {
  // Typed absence is first-class integrity, not a failure.
  if (fact.silentReason || fact.value == null) {
    return { kind: 'SILENT', reason: fact.silentReason ?? 'no-signal' };
  }
  const hasSource = !!fact.source;

  // The cardinal sin: confident claim with no source.
  if (fact.confidence != null && fact.confidence >= CARDINAL_CONFIDENCE && !hasSource) {
    return { kind: 'VIOLATION', reason: 'confident claim with no source', cardinal: true };
  }
  // Provenance is mandatory for any real claim.
  if (!hasSource || fact.observedAt == null) {
    return { kind: 'VIOLATION', reason: 'missing provenance (source/observedAt)', cardinal: false };
  }
  // Staleness: past its freshness window => strip, don't speak as current.
  const ttl = (fact.ttlMinutes ?? DEFAULT_TTL_MINUTES) * 60_000;
  if (now - fact.observedAt > ttl) {
    return { kind: 'VIOLATION', reason: 'stale beyond TTL', cardinal: false };
  }
  return { kind: 'GROUNDED', fact };
}

// Only GROUNDED facts are handed to the model. VIOLATIONs are dropped;
// SILENTs are passed to the render layer as typed absence to handle deliberately.
export function forModel(facts: Fact[], now = Date.now()): { grounded: Fact[]; silent: Verdict[] } {
  const grounded: Fact[] = [];
  const silent: Verdict[] = [];
  for (const f of facts) {
    const v = classify(f, now);
    if (v.kind === 'GROUNDED') grounded.push(v.fact);
    else if (v.kind === 'SILENT') silent.push(v);
    // VIOLATION: intentionally dropped — never reaches the model or the user.
  }
  return { grounded, silent };
}

// The grounding metric — silence counts as integrity, only violations count against.
export function groundingRate(facts: Fact[], now = Date.now()): number {
  let ok = 0, violation = 0;
  for (const f of facts) {
    const v = classify(f, now);
    if (v.kind === 'VIOLATION') violation++;
    else ok++; // GROUNDED and SILENT both count as integrity
  }
  const total = ok + violation;
  return total === 0 ? 1 : ok / total;
}

// The grade primitive (step 7): re-run today's rules over a historical snapshot,
// so accuracy fixes are evidence-driven across the population, not anecdote-driven.
export function grade(snapshot: Fact[], now = Date.now()): { rate: number; violations: Verdict[] } {
  const violations = snapshot
    .map(f => classify(f, now))
    .filter((v): v is Extract<Verdict, { kind: 'VIOLATION' }> => v.kind === 'VIOLATION');
  return { rate: groundingRate(snapshot, now), violations };
}
